import java.io.*;import java.nio.file.*;import java.util.*;import com.jpexs.decompiler.flash.SWF;import com.jpexs.decompiler.flash.tags.Tag;
class SocialBridgeAudit{
 static Set<String> classes(SWF s){Set<String> out=new TreeSet<>();for(var p:s.getAS3Packs())if(!out.add(p.getClassPath().toString()))throw new IllegalStateException("Duplicate class");return out;}
 static byte[] bytes(com.jpexs.decompiler.flash.abc.ABC a)throws Exception{var out=new ByteArrayOutputStream();a.saveTo(out);return out.toByteArray();}
 public static void main(String[]args)throws Exception{SWF before=new SWF(new FileInputStream(args[0]),true),candidate=new SWF(new FileInputStream(args[1]),true),helper=new SWF(new FileInputStream(args[2]),true);Set<String> declared=Set.of("SocialMarriageBridge");if(!classes(helper).equals(declared))throw new IllegalStateException("Unexpected helper classes "+classes(helper));var expected=classes(before);expected.addAll(declared);if(!classes(candidate).equals(expected))throw new IllegalStateException("Original classes changed or undocumented classes added");for(String name:declared){var a=helper.getAS3Packs().stream().filter(p->p.getClassPath().toString().equals(name)).findFirst().get().abc;var b=candidate.getAS3Packs().stream().filter(p->p.getClassPath().toString().equals(name)).findFirst().get().abc;if(!Arrays.equals(bytes(a),bytes(b)))throw new IllegalStateException("Compatibility bytecode differs: "+name);}System.out.println("bridge-isolated-and-byte-identical classes="+classes(candidate).size());}
}
